CREATE COLUMN TABLE "TEST_AP"."OBGD" ("BgdCode" INTEGER CS_INT NOT NULL , "BgdName" NVARCHAR(30) NOT NULL , "BgdTotal" DECIMAL(21,6) CS_FIXED, "Month1" DECIMAL(21,6) CS_FIXED, "Month2" DECIMAL(21,6) CS_FIXED, "Month3" DECIMAL(21,6) CS_FIXED, "Month4" DECIMAL(21,6) CS_FIXED, "Month5" DECIMAL(21,6) CS_FIXED, "Month6" DECIMAL(21,6) CS_FIXED, "Month7" DECIMAL(21,6) CS_FIXED, "Month8" DECIMAL(21,6) CS_FIXED, "Month9" DECIMAL(21,6) CS_FIXED, "Month10" DECIMAL(21,6) CS_FIXED, "Month11" DECIMAL(21,6) CS_FIXED, "Month12" DECIMAL(21,6) CS_FIXED, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("BgdCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBGD_NAME" ON "TEST_AP"."OBGD" ( "BgdName" ASC )